def gap(n):
    """Compute the initial gap size for Comb Sort."""
    gap = n
    while gap > 0:
        gap //= 2
    return gap

def swap_elements(arr, i, j):
    """Helper function to swap elements at indices i and j in the array."""
    arr[i], arr[j] = arr[j], arr[i]

def comb_sort(arr):
    n = len(arr)
    gap = gap(n)

    while gap > 1 or n > 1:
        gap = max(1, int(gap / 1.3))  # Update gap size using shrink factor

        for i in range(n - gap):
            for j in range(i + gap, n, gap):
                if arr[i] > arr[j]:
                    swap_elements(arr, i, j)

        n -= 1
    return arr

