def is_samepatterns(patterns):
    def compare_sequences(seq1, seq2):
        return len(seq1) == len(seq2) and all(a == b or a == '_' or b == '_' for a, b in zip(seq1, seq2))

    if not patterns:
        return True

    first_seq = patterns[0]
    for seq in patterns[1:]:
        if not compare_sequences(first_seq, seq):
            return False
    return True

